import{_ as a,c as t,a2 as n,o}from"./chunks/framework.Bzjhwp8w.js";const m=JSON.parse('{"title":"Langflow 文档","description":"Langflow - 轻松构建 LangChain 流程的用户界面","frontmatter":{"title":"Langflow 文档","description":"Langflow - 轻松构建 LangChain 流程的用户界面","layout":"doc"},"headers":[],"relativePath":"langflow/index.md","filePath":"langflow/index.md"}'),e={name:"langflow/index.md"};function i(r,l,h,f,g,s){return o(),t("div",null,l[0]||(l[0]=[n('<h1 id="langflow-文档" tabindex="-1">Langflow 文档 <a class="header-anchor" href="#langflow-文档" aria-label="Permalink to &quot;Langflow 文档&quot;">​</a></h1><p>欢迎来到 Langflow 文档！Langflow 是一个强大的工具，可以帮助您以可视化方式轻松构建 LangChain 流程。</p><h2 id="什么是-langflow" tabindex="-1">什么是 Langflow? <a class="header-anchor" href="#什么是-langflow" aria-label="Permalink to &quot;什么是 Langflow?&quot;">​</a></h2><p>Langflow 是一个用于 LangChain 的 UI 构建器，具有以下特点：</p><ul><li>🎨 <strong>拖拽式界面</strong> - 通过直观的拖拽操作创建复杂的 LangChain 流程</li><li>🔗 <strong>组件连接</strong> - 轻松连接不同的 LangChain 组件</li><li>📝 <strong>实时编辑</strong> - 随时调整组件参数和配置</li><li>🚀 <strong>即时部署</strong> - 快速导出和部署您的流程</li><li>🛠️ <strong>可扩展</strong> - 支持自定义组件开发</li></ul><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><p>要开始使用 Langflow，您可以：</p><ol><li><a href="/dllm/langflow/get-started-installation.html">安装 Langflow</a> - 了解如何安装和运行 Langflow</li><li><a href="/dllm/langflow/get-started-quickstart.html">快速入门指南</a> - 创建您的第一个流程</li><li><a href="/dllm/langflow/starter-projects-basic-prompting.html">基础提示示例</a> - 学习基本的提示工程</li></ol><h2 id="示例项目" tabindex="-1">示例项目 <a class="header-anchor" href="#示例项目" aria-label="Permalink to &quot;示例项目&quot;">​</a></h2><p>我们提供了多个示例项目帮助您学习：</p><ul><li><a href="/dllm/langflow/tutorials-document-qa.html">文档问答系统</a></li><li><a href="/dllm/langflow/tutorials-memory-chatbot.html">带记忆的聊天机器人</a></li><li><a href="/dllm/langflow/tutorials-math-agent.html">数学问题求解代理</a></li><li><a href="/dllm/langflow/tutorials-travel-planning-agent.html">旅行规划代理</a></li></ul><h2 id="深入了解" tabindex="-1">深入了解 <a class="header-anchor" href="#深入了解" aria-label="Permalink to &quot;深入了解&quot;">​</a></h2><p>要深入了解 Langflow，请查看：</p><ul><li><a href="/dllm/langflow/concepts-overview.html">Langflow 概述</a></li><li><a href="/dllm/langflow/concepts-components.html">组件概览</a></li><li><a href="/dllm/langflow/concepts-playground.html">Playground 使用指南</a></li></ul><h2 id="社区支持" tabindex="-1">社区支持 <a class="header-anchor" href="#社区支持" aria-label="Permalink to &quot;社区支持&quot;">​</a></h2><p>加入我们的社区：</p><ul><li><a href="/dllm/langflow/contributing-how-to-contribute.html">参与贡献</a></li><li><a href="https://github.com/logspace-ai/langflow/discussions" target="_blank" rel="noreferrer">GitHub 讨论</a></li><li><a href="/dllm/langflow/contributing-github-issues.html">报告问题</a></li></ul><h2 id="部署指南" tabindex="-1">部署指南 <a class="header-anchor" href="#部署指南" aria-label="Permalink to &quot;部署指南&quot;">​</a></h2><p>了解如何部署 Langflow：</p><ul><li><a href="/dllm/langflow/deployment-docker.html">Docker 部署</a></li><li><a href="/dllm/langflow/deployment-kubernetes.html">Kubernetes 部署</a></li><li><a href="/dllm/langflow/deployment-gcp.html">云平台部署</a></li></ul><hr><p>准备好开始了吗？<a href="/dllm/langflow/get-started-installation.html">立即安装 Langflow</a> 开始您的 AI 应用构建之旅！</p>',22)]))}const c=a(e,[["render",i]]);export{m as __pageData,c as default};
